-- MySQL 8 compatible schema. Run inside a dedicated linjun_library database.
CREATE TABLE IF NOT EXISTS account (id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(60) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, name VARCHAR(80) NOT NULL, role VARCHAR(20) NOT NULL, enabled INT NOT NULL DEFAULT 1, student_no VARCHAR(40) UNIQUE, department VARCHAR(80), phone VARCHAR(30), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS category (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, description VARCHAR(255), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS book (id BIGINT AUTO_INCREMENT PRIMARY KEY, isbn VARCHAR(30) NOT NULL UNIQUE, title VARCHAR(150) NOT NULL, author VARCHAR(100), publisher VARCHAR(120), category_id BIGINT, location VARCHAR(100), description VARCHAR(1000), enabled INT NOT NULL DEFAULT 1, FOREIGN KEY(category_id) REFERENCES category(id), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS book_copy (id BIGINT AUTO_INCREMENT PRIMARY KEY, book_id BIGINT NOT NULL, code VARCHAR(60) NOT NULL UNIQUE, status VARCHAR(20) NOT NULL DEFAULT 'AVAILABLE', FOREIGN KEY(book_id) REFERENCES book(id), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS acquisition (id BIGINT AUTO_INCREMENT PRIMARY KEY, book_id BIGINT NOT NULL, quantity INT NOT NULL, source VARCHAR(150), operator_id BIGINT NOT NULL, FOREIGN KEY(book_id) REFERENCES book(id), FOREIGN KEY(operator_id) REFERENCES account(id), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS loan (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, copy_id BIGINT NOT NULL, borrowed_at TIMESTAMP NOT NULL, due_at TIMESTAMP NOT NULL, returned_at TIMESTAMP NULL, status VARCHAR(20) NOT NULL, operator_id BIGINT NOT NULL, FOREIGN KEY(user_id) REFERENCES account(id), FOREIGN KEY(copy_id) REFERENCES book_copy(id), FOREIGN KEY(operator_id) REFERENCES account(id), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS fine (id BIGINT AUTO_INCREMENT PRIMARY KEY, loan_id BIGINT NOT NULL UNIQUE, amount DECIMAL(10,2) NOT NULL, overdue_days INT NOT NULL, status VARCHAR(20) NOT NULL, FOREIGN KEY(loan_id) REFERENCES loan(id), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS blacklist (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, reason VARCHAR(255) NOT NULL, active INT NOT NULL DEFAULT 1, operator_id BIGINT NOT NULL, FOREIGN KEY(user_id) REFERENCES account(id), FOREIGN KEY(operator_id) REFERENCES account(id), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS resource (id BIGINT AUTO_INCREMENT PRIMARY KEY, kind VARCHAR(20) NOT NULL, code VARCHAR(60) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, location VARCHAR(120), capacity INT NOT NULL DEFAULT 1, status VARCHAR(20) NOT NULL DEFAULT 'OPEN', equipment_status VARCHAR(20) NOT NULL DEFAULT 'NORMAL', description VARCHAR(500), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reservation (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, resource_id BIGINT NOT NULL, start_at TIMESTAMP NOT NULL, end_at TIMESTAMP NOT NULL, purpose VARCHAR(255), organization VARCHAR(100), status VARCHAR(20) NOT NULL, checked_in_at TIMESTAMP NULL, reviewed_by BIGINT, review_note VARCHAR(255), violation INT NOT NULL DEFAULT 0, FOREIGN KEY(user_id) REFERENCES account(id), FOREIGN KEY(resource_id) REFERENCES resource(id), FOREIGN KEY(reviewed_by) REFERENCES account(id), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS activity (id BIGINT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(150) NOT NULL, description VARCHAR(2000), resource_id BIGINT NOT NULL, start_at TIMESTAMP NOT NULL, end_at TIMESTAMP NOT NULL, max_people INT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'OPEN', FOREIGN KEY(resource_id) REFERENCES resource(id), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS registration (id BIGINT AUTO_INCREMENT PRIMARY KEY, activity_id BIGINT NOT NULL, user_id BIGINT NOT NULL, status VARCHAR(20) NOT NULL, checked_in_at TIMESTAMP NULL, UNIQUE(activity_id,user_id), FOREIGN KEY(activity_id) REFERENCES activity(id), FOREIGN KEY(user_id) REFERENCES account(id), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS announcement (id BIGINT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(150) NOT NULL, content TEXT NOT NULL, pinned INT NOT NULL DEFAULT 0, author_id BIGINT NOT NULL, FOREIGN KEY(author_id) REFERENCES account(id), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS visit (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT, visitor_name VARCHAR(80), identity_ref VARCHAR(80), entered_at TIMESTAMP NOT NULL, operator_id BIGINT NOT NULL, FOREIGN KEY(user_id) REFERENCES account(id), FOREIGN KEY(operator_id) REFERENCES account(id), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS auth_token (id BIGINT AUTO_INCREMENT PRIMARY KEY, token_hash VARCHAR(64) NOT NULL UNIQUE, user_id BIGINT NOT NULL, expires_at TIMESTAMP NOT NULL, FOREIGN KEY(user_id) REFERENCES account(id));
CREATE INDEX idx_loan_user ON loan(user_id,status);
CREATE INDEX idx_reservation_resource ON reservation(resource_id,start_at,end_at,status);
CREATE INDEX idx_blacklist_user ON blacklist(user_id,active);
CREATE INDEX idx_visit_date ON visit(entered_at);
